[
  {
    "title": "fight-button-overlaps-feet",
    "claim": "In 01-phone-title, the FIGHT button obscures the fighters’ forward-foot area, whereas 02-phone-fight shows those feet unobstructed.",
    "reason": "The opening composition hides part of the fighting stances directly behind its primary action.",
    "suggest": "Reserve an unobstructed band for FIGHT below the fighters, adjusting the opening composition rather than shrinking the button."
  },
  {
    "title": "undefined-neutral-symbol",
    "claim": "The visible portion of 05-phone-techref uses a dot for Lunge Punch’s stance input without explaining what that dot means.",
    "reason": "A beginner cannot distinguish an instruction to center the stick from an instruction to press or touch its center.",
    "suggest": "Add a plain-language definition beside the top input legend that states the dot’s verified input meaning."
  },
  {
    "title": "ambiguous-point-values",
    "claim": "In 05-phone-techref, the paragraph associates half points with partial contact, while individual move rows list Half point or Full point without identifying those values as fixed awards or maximum awards.",
    "reason": "These adjacent explanations leave unclear whether scoring depends on the selected technique, contact quality, or both.",
    "suggest": "Identify the row values explicitly as fixed or maximum awards after checking the scoring rule, and revise the paragraph to explain that same relationship."
  },
  {
    "title": "missing-desktop-key-legend",
    "claim": "08-desktop-fight shows STANCE and TECHNIQUE stick graphics but no visible keyboard bindings.",
    "reason": "A desktop player cannot learn the supported keyboard controls from this screen.",
    "suggest": "Display the verified stance and technique key bindings in the unused lower-center area when keyboard input is selected."
  },
  {
    "title": "text-size-unverified",
    "claim": "The HUD names, stick captions, and technique award labels are visible, but these screenshots cannot establish their computed CSS font sizes.",
    "reason": "Raster display scaling is not evidence that the required 18 CSS px minimum either passes or fails.",
    "suggest": "Measure computed font sizes and ancestor scaling at 390×844 and desktop width; enlarge any text below 18 CSS px and reflow its surrounding layout rather than compressing it."
  }
]
